import{_ as s,o as t,c as o,a5 as e}from"./chunks/framework.DGp912Ge.js";const b=JSON.parse('{"title":"RBQ 시뮬레이터","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/simulator/overview.md","filePath":"ko/software/simulator/overview.md","lastUpdated":1781685147000}'),i={name:"ko/software/simulator/overview.md"};function n(l,a,r,p,d,h){return t(),o("div",null,[...a[0]||(a[0]=[e(`<h1 id="rbq-시뮬레이터" tabindex="-1">RBQ 시뮬레이터 <a class="header-anchor" href="#rbq-시뮬레이터" aria-label="Permalink to &quot;RBQ 시뮬레이터&quot;">​</a></h1><p>RBQ 오픈소스 패키지에는 <strong>목적이 다른</strong> 두 종류의 시뮬레이터가 포함되어 있습니다:</p><ul><li><strong>오픈소스 물리 시뮬레이터</strong> — <a href="/RBQ/ko/software/simulator/mujoco.html">MuJoCo</a>와 <a href="/RBQ/ko/software/simulator/gazebo.html">Gazebo</a>는 시뮬레이션 위에서 <strong>RBQ 소프트웨어 스택 전체</strong>(Motion / Vision / GUI)를 실행하여, 하드웨어 없이 로봇 소프트웨어를 개발·검증할 수 있게 합니다.</li><li><strong>강화학습 학습 환경</strong> — <a href="/RBQ/ko/software/simulator/rbq-gym.html">Isaac Gym</a>과 <a href="/RBQ/ko/software/simulator/rbq-lab.html">Isaac Lab</a>은 보행 정책을 <strong>학습</strong>하고 실제 로봇에 <strong>배포</strong>할 수 있게 합니다.</li></ul><h2 id="시뮬레이터" tabindex="-1">시뮬레이터 <a class="header-anchor" href="#시뮬레이터" aria-label="Permalink to &quot;시뮬레이터&quot;">​</a></h2><table tabindex="0"><thead><tr><th>시뮬레이터</th><th>엔진</th><th>패키지 경로</th><th>목적</th></tr></thead><tbody><tr><td><strong>MuJoCo</strong></td><td>MuJoCo</td><td><code>rbq_simulator/rbq_mujoco/</code></td><td>스택 전체를 시뮬레이션에서 실행</td></tr><tr><td><strong>Gazebo</strong></td><td>Ignition Gazebo (Fortress)</td><td><code>rbq_simulator/rbq_gazebo/</code></td><td>스택 전체를 시뮬레이션에서 실행 (ROS 2 센서 브리지 포함)</td></tr><tr><td><strong>Isaac Gym</strong></td><td>IsaacGym (Preview 4)</td><td><code>rbq_simulator/rbq_gym/</code></td><td>강화학습 — 빠른 병렬 학습</td></tr><tr><td><strong>Isaac Lab</strong></td><td>Isaac Sim / Isaac Lab</td><td><code>rbq_simulator/rbq_lab/</code></td><td>강화학습 — 고정밀 시뮬레이션</td></tr></tbody></table><h2 id="rbq-스택-전체-실행-mujoco-gazebo" tabindex="-1">RBQ 스택 전체 실행 (MuJoCo / Gazebo) <a class="header-anchor" href="#rbq-스택-전체-실행-mujoco-gazebo" aria-label="Permalink to &quot;RBQ 스택 전체 실행 (MuJoCo / Gazebo)&quot;">​</a></h2><p>MuJoCo와 Gazebo는 도메인 0 / 루프백에서 DDS 피어로 실행 중인 RBQ 스택에 참여합니다. 스택을 먼저 실행한 뒤 시뮬레이터를 실행합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># RBQ 스택 실행 (Motion / Vision / GUI)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sim</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 이후 시뮬레이터 실행, 예: MuJoCo</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_mujoco</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_mujoco</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resources/model/default.xml</span></span></code></pre></div><p>전체 빌드·실행 방법은 <a href="/RBQ/ko/software/simulator/mujoco.html">MuJoCo</a>와 <a href="/RBQ/ko/software/simulator/gazebo.html">Gazebo</a>를 참조하세요.</p><h2 id="정책-학습-배포-isaac-gym-isaac-lab" tabindex="-1">정책 학습 &amp; 배포 (Isaac Gym / Isaac Lab) <a class="header-anchor" href="#정책-학습-배포-isaac-gym-isaac-lab" aria-label="Permalink to &quot;정책 학습 &amp; 배포 (Isaac Gym / Isaac Lab)&quot;">​</a></h2><p>강화학습 환경은 동일한 <strong>Train → Play → Deploy</strong> 파이프라인을 따릅니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Train (Isaac Gym 또는 Isaac Lab)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Play (같은 시뮬레이터에서 정책 검증)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Sim2Sim (MuJoCo, rbq_low_level을 통해)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Deploy (실제 로봇)</span></span></code></pre></div><p>학습 완료 후 <code>policy.onnx</code>와 <code>info.json</code>을 <code>rbq_low_level</code>에 로드해 로봇에서 실행합니다.</p><h2 id="저장소-구조" tabindex="-1">저장소 구조 <a class="header-anchor" href="#저장소-구조" aria-label="Permalink to &quot;저장소 구조&quot;">​</a></h2><p>시뮬레이터 코드는 <code>rbq_simulator/</code> 아래에 있습니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RBQ/</span></span>
<span class="line"><span>└── rbq_simulator/</span></span>
<span class="line"><span>    ├── rbq_mujoco/        # MuJoCo 시뮬레이터 (스택 전체)</span></span>
<span class="line"><span>    ├── rbq_gazebo/        # Ignition Gazebo 시뮬레이터 (스택 전체 + ROS 2 브리지)</span></span>
<span class="line"><span>    ├── rbq_gym/           # Isaac Gym 강화학습 환경</span></span>
<span class="line"><span>    └── rbq_lab/           # Isaac Lab 강화학습 환경</span></span></code></pre></div><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><ul><li><a href="/RBQ/ko/software/simulator/mujoco.html">MuJoCo →</a> — MuJoCo에서 스택 전체 실행</li><li><a href="/RBQ/ko/software/simulator/gazebo.html">Gazebo →</a> — Gazebo에서 스택 전체 실행</li><li><a href="/RBQ/ko/software/simulator/rbq-gym.html">Isaac Gym →</a> — Isaac Gym 학습 가이드</li><li><a href="/RBQ/ko/software/simulator/rbq-lab.html">Isaac Lab →</a> — Isaac Lab 학습 가이드</li><li><a href="/RBQ/ko/software/sdk/cpp/low-level.html">Low Level (RL 정책) →</a> — 학습된 정책을 실제 로봇에 배포</li></ul>`,18)])])}const m=s(i,[["render",n]]);export{b as __pageData,m as default};
